(function(){
let definitions,records=[],departments=[],type=2,current=null,filterDate='',historyOrigin=false;
const I=window.fireI18n;
const safe=value=>esc(String(value??''));
const text=key=>safe(I.t(key));
const label=key=>I.html(key);
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Taipei',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const manager=()=>['admin','supervisor'].includes(profile?.role);
const deptName=id=>{const d=departments.find(x=>x.id===id);return d?multilingual({zh:d.name_zh,en:d.name_en,es:d.name_es,vi:d.name_vi}):'';};
const statusKey=value=>value==='confirmed'?'confirmed':value==='submitted'?'submitted':'draftStatus';
const statusText=value=>I.html(statusKey(value));
const titleKey=n=>n===1?'dailyTitle':n===2?'escapeTitle':'equipmentTitle';
window.fireFormTabs=selected=>`<nav class="fire-form-tabs" aria-label="${safe(I.t('criterion'))}">${[1,2,3].map(n=>`<button type="button" data-fire-form-tab="${n}" class="${selected===n?'active':''}">${safe(I.t('appendix'))} ${n}　${safe(I.t(titleKey(n)))}</button>`).join('')}<button type="button" data-fire-form-tab="4" class="${selected===4?'active':''}">簽核紀錄 / Approval history</button></nav>`;
window.bindFireFormTabs=()=>document.querySelectorAll('[data-fire-form-tab]').forEach(b=>b.onclick=()=>{const n=Number(b.dataset.fireFormTab);if(n===1)window.renderFireDaily();else if(n===4)window.renderFireApprovalHistory();else window.renderFireAttachments(n);});
async function load(){
 if(!definitions){const response=await fetch('/fire-attachments-data.json?v=86');if(!response.ok)throw Error('form_definition_unavailable');definitions=await response.json();}
 const result=await api({action:'fire_attachment_list',form_type:type});records=result.records||[];departments=result.departments||[];
}
function blank(){return {id:crypto.randomUUID(),form_type:type,inspection_date:today(),department_id:departments.find(d=>d.id===profile?.department_id)?.id||departments[0]?.id||'',responsible_area:'',implementer_name:localStorage.getItem('inspection_operator_name')||'',entries:Array.from({length:9},(_,i)=>({item:i+1,status:'',note:''})),situation_report:'',manager_name:'',manager_disposition:'',manager_signature:'',owner_disposition:'',owner_signature:'',status:'draft',updated_at:null};}
function list(){
 $('#content').innerHTML=window.fireFormTabs(type)+`<div class="filter-row"><label>${label('date')}<input id="fireAttachmentDateFilter" type="date" class="select" value="${safe(filterDate)}"></label><button id="fireAttachmentNew" class="btn primary">${text('new')} ${text('appendix')} ${type}</button></div><div class="table-wrap"><table class="matrix"><thead><tr>${['date','department','area','implementer','status','action'].map(key=>`<th>${label(key)}</th>`).join('')}</tr></thead><tbody>${records.filter(r=>!filterDate||r.inspection_date===filterDate).map(r=>`<tr><td>${safe(r.inspection_date)}</td><td>${safe(deptName(r.department_id))}</td><td>${safe(r.responsible_area)}</td><td>${safe(r.implementer_name)}</td><td>${statusText(r.status)}</td><td><button class="btn secondary" data-attachment-open="${safe(r.id)}">${text(r.status==='submitted'&&manager()?'review':'view')}</button></td></tr>`).join('')}</tbody></table></div>`;
 window.bindFireFormTabs();$('#fireAttachmentDateFilter').onchange=e=>{filterDate=e.target.value;list();};$('#fireAttachmentNew').onclick=()=>{current=blank();editor();};document.querySelectorAll('[data-attachment-open]').forEach(b=>b.onclick=()=>{current=structuredClone(records.find(r=>r.id===b.dataset.attachmentOpen));editor();});
}
function originalText(item,lang){
 const lines=String(item.text||'').split('\n');
 if(lang==='zh')return lines.filter(line=>/[\u3400-\u9fff]/.test(line)).map(line=>line.replace(/Khu vực.*$/,'').trim()).filter(Boolean).join('\n');
 return lines.filter(line=>!/[\u3400-\u9fff]/.test(line)).concat(lines.map(line=>line.match(/Khu vực.*$/)?.[0]).filter(Boolean)).join('\n');
}
function itemText(item,index){return I.chosen().map((lang,order)=>{const value=I.itemText(type,index,lang)||originalText(item,lang);return `<span class="${order?'fire-translation':'fire-main-translation'}" lang="${lang==='zh'?'zh-Hant':lang}">${safe(value)}</span>`;}).join('');}
function equipmentName(index){return I.chosen().map((lang,order)=>`<span class="${order?'fire-translation':'fire-main-translation'}" lang="${lang==='zh'?'zh-Hant':lang}">${safe(I.equipmentNames[index][{zh:0,en:1,es:2,vi:3}[lang]])}</span>`).join('');}
function selector(index,item,locked){const options=[['O',`Ｏ ${text('compliant')}`],['V',`Ｖ ${text('corrected')}`],['X',`Ｘ ${text('abnormal')}`],['NA',text('na')]];return `<select data-attachment-status="${index}" aria-label="${text('result')} ${index+1}" ${locked?'disabled':''}><option value="" ${!item.status?'selected':''}>—</option>${options.map(([value,display])=>`<option value="${value}" ${item.status===value?'selected':''}>${display}</option>`).join('')}</select>`;}
function editor(){
 const r=current,locked=r.status!=='draft',def=definitions[String(type)];
 const rows=def.items.map((item,i)=>`<tr><td class="fire-attachment-number">${i+1}</td>${type===3?`<td class="fire-attachment-equipment">${equipmentName(i)}</td>`:''}<td class="fire-attachment-criterion">${itemText(item,i)}</td><td>${selector(i,r.entries[i]||{},locked)}</td><td><textarea data-attachment-note="${i}" rows="2" maxlength="1000" ${locked?'disabled':''}>${safe(r.entries[i]?.note)}</textarea></td></tr>`).join('');
 $('#content').innerHTML=window.fireFormTabs(type)+`<section class="fire-form fire-sheet fire-attachment-sheet"><div class="filter-row"><button id="fireAttachmentBack" class="btn secondary">${text('back')}</button><button id="fireAttachmentPrint" class="btn secondary">${text('print')}</button>${!locked?`<button id="fireAttachmentQuick" class="btn secondary">${text('quick')}</button>`:''}<span class="tag ${r.status==='confirmed'?'normal':r.status==='submitted'?'pending':'none'}">${statusText(r.status)}</span></div><header class="fire-document-heading"><span class="fire-appendix">${label('appendix')} ${type}</span><div class="fire-document-title"><strong>${label(titleKey(type))}</strong></div></header><div class="fire-fields"><label>${label('implementer')}<input id="fireAttachmentImplementer" class="select" maxlength="100" value="${safe(r.implementer_name)}" ${locked?'disabled':''}></label><label>${label('area')}<input id="fireAttachmentArea" class="select" maxlength="200" value="${safe(r.responsible_area)}" ${locked?'disabled':''}></label><label>${label('date')}<input id="fireAttachmentDate" class="select" type="date" value="${safe(r.inspection_date)}" max="${today()}" ${locked?'disabled':''}></label><label>${label('department')}<select id="fireAttachmentDept" class="select" ${locked?'disabled':''}>${departments.map(d=>`<option value="${safe(d.id)}" ${d.id===r.department_id?'selected':''}>${safe(deptName(d.id))}</option>`).join('')}</select></label></div><div class="table-wrap fire-grid"><table class="matrix"><thead><tr><th>${label('item')}</th>${type===3?`<th>${label('equipment')}</th>`:''}<th>${label('criterion')}</th><th>${label('result')}</th><th>${label('note')}</th></tr></thead><tbody>${rows}</tbody></table></div>${type===2?`<label class="fire-attachment-report">${label('report')}<textarea id="fireAttachmentReport" rows="3" maxlength="2000" ${locked?'disabled':''}>${safe(r.situation_report)}</textarea></label>`:''}<div class="fire-attachment-signoffs"><section><h3>${label('managerSection')}</h3><div id="fireAttachmentManager"></div></section><section><h3>${label('ownerSection')}</h3><div id="fireAttachmentOwner"></div></section></div><div class="fire-legend">${label('legend')}</div><div class="fire-notice">${label('notice')}</div>${!locked?`<div class="fire-actions"><button id="fireAttachmentDraft" class="btn secondary">${text('draft')}</button><button id="fireAttachmentSubmit" class="btn primary">${text('submit')}</button></div>`:''}${r.status==='submitted'&&manager()?`<div class="fire-actions"><button id="fireAttachmentConfirm" class="btn primary">${text('confirm')}</button><button id="fireAttachmentReturn" class="btn danger">${text('return')}</button></div>`:''}</section>`;
 window.bindFireFormTabs();$('#fireAttachmentBack').onclick=()=>historyOrigin?window.renderFireApprovalHistory():list();$('#fireAttachmentPrint').onclick=()=>window.printFireForm();
 const mgr=$('#fireAttachmentManager'),owner=$('#fireAttachmentOwner');
 if(r.status==='submitted'&&manager()){
  mgr.innerHTML=`<label>${label('managerName')}<input id="fireAttachmentManagerName" maxlength="100" value="${safe(r.manager_name)}"></label><label>${label('disposition')}<textarea id="fireAttachmentDisposition" maxlength="2000" rows="3">${safe(r.manager_disposition)}</textarea></label><label>${label('signature')}<input id="fireAttachmentSignature" maxlength="100" value="${safe(r.manager_signature)}"></label>`;
  owner.innerHTML=`<p><span data-fire-print-action>${safe(r.owner_disposition)}</span>　<span data-fire-print-signature>${safe(r.owner_signature)}</span></p>`;
  $('#fireAttachmentConfirm').onclick=()=>review('confirm');$('#fireAttachmentReturn').onclick=()=>review('return');
 }else{mgr.innerHTML=`<p><span data-fire-print-name>${safe(r.manager_name)}</span>　<span data-fire-print-action>${safe(r.manager_disposition)}</span>　<span data-fire-print-signature>${safe(r.manager_signature)}</span></p>`;owner.innerHTML=`<p><span data-fire-print-action>${safe(r.owner_disposition)}</span>　<span data-fire-print-signature>${safe(r.owner_signature)}</span></p>`;}
 if(!locked){$('#fireAttachmentQuick').onclick=()=>{document.querySelectorAll('[data-attachment-status]').forEach(el=>{if(!el.value)el.value='O';});};$('#fireAttachmentDraft').onclick=()=>save('draft');$('#fireAttachmentSubmit').onclick=()=>save('submitted');}
}
async function save(status){const r=current;const entries=[...document.querySelectorAll('[data-attachment-status]')].map((el,i)=>({item:i+1,status:el.value,note:document.querySelector(`[data-attachment-note="${i}"]`).value}));const next={...r,form_type:type,department_id:$('#fireAttachmentDept').value,inspection_date:$('#fireAttachmentDate').value,responsible_area:$('#fireAttachmentArea').value.trim(),implementer_name:$('#fireAttachmentImplementer').value.trim(),situation_report:$('#fireAttachmentReport')?.value||'',entries,status};if(!next.responsible_area||!next.implementer_name||!next.inspection_date){toast('error','請填寫實施人員、負責區域及日期');return;}if(status==='submitted'&&entries.some(x=>!x.status)){toast('error','請完成全部 9 項檢查結果');return;}try{const out=await api({action:'fire_attachment_save',form_type:type,record:next});current=out.record;records=records.filter(x=>x.id!==current.id).concat(current);toast('saved');editor();}catch(e){toast('error',e.message||'');}}
async function review(decision){const values={action:'fire_attachment_review',form_type:type,id:current.id,updated_at:current.updated_at,manager_name:$('#fireAttachmentManagerName').value.trim(),manager_disposition:$('#fireAttachmentDisposition').value.trim(),manager_signature:$('#fireAttachmentSignature').value.trim(),decision};if(!values.manager_name||!values.manager_disposition||!values.manager_signature){toast('error','請填寫防火管理人姓名、處置情形及簽章');return;}try{const out=await api(values);current=out.record;records=records.filter(x=>x.id!==current.id).concat(current);toast('saved');editor();}catch(e){toast('error',e.message||'');}}
window.renderFireAttachments=async function(formType){type=formType;historyOrigin=false;try{await load();list();}catch(e){$('#content').innerHTML=window.fireFormTabs(type)+`<div class="empty-note">無法讀取附件 ${type}：${safe(e.message)}</div>`;window.bindFireFormTabs();}};
window.openFireAttachmentRecord=async function(formType,id){type=Number(formType);try{await load();const found=records.find(r=>r.id===id&&r.status==='confirmed');if(!found)throw Error('record_unavailable');current=structuredClone(found);historyOrigin=true;editor();}catch(e){$('#content').innerHTML=window.fireFormTabs(4)+`<div class="empty-note">無法開啟簽核紀錄：${safe(e.message)}</div>`;window.bindFireFormTabs();}};
})();
